#include <boost/log/trivial.hpp>
#include <boost/thread/locks.hpp>
#include <boost/asio/io_service.hpp>

namespace fs = boost::filesystem;
namespace po = boost::program_options;
namespace bslg = boost::log;

class Config {
public:
    int bufferSize, lineProcessCount;
    std::string configFile, inputFile, outputFile;
};

// ... other classes and functions for reading chunks from file and processing them concurrently

int main(int argc, char* argv[]) {
    Config cfg;
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help", "Print help message.")
        ("version", "Print version information.")
        ("config,c", po::value<std::string>(&cfg.configFile), "Configuration file path.")
        ("f,input", po::value<std::string>(&cfg.inputFile), "Input file path.")
        ("o,output", po::value<std::string>(&cfg.outputFile), "Output file path.")
        ("lines,n", po::value<int>(&cfg.lineProcessCount)->default_value(4096), "Number of lines to process before saving results.");

    po::variables_map vm;
    try {
        po::store(po::parse_command_line(argc, argv, desc), vm);
        po::notify(vm);
    } catch (const po::error& e) {
        std::cerr << "Error parsing command-line options: " << e.what() << "\n";
        std::cout << desc;
        return 1;
    }

    // Load configuration from file, handle errors and initialize other parts of your program
    // ...

    // Process the input file
    // ...

    return 0;
}
```

This code provides a basic structure for your C++ command-line utility. You'll need to fill in the details for reading chunks from the file, processing them concurrently, and handling errors such as missing or corrupted files. Remember to also implement clear separation of concerns, unit tests covering critical functionalities, and optimize your code for scalability and performance under high load. Good luck!']

