class SessionUUID {
public:
    explicit SessionUUID(const std::string& str) : uuid_(str) {}
    const std::string& getUuid() const { return uuid_; }
private:
    std::string uuid_;
};

class SessionStorageService {
public:
    virtual ~SessionStorageService() = default;
    virtual void writeSession(const SessionUUID& sessionId) = 0;
    virtual std::vector<SessionUUID> readSessions() = 0;
};

class CircuitBreaker {
public:
    explicit CircuitBreaker(std::shared_ptr<SessionStorageService> service, int maxFailures, int cooldown)
        : service_(service), maxFailures_(maxFailures), cooldown_(cooldown), currentAttempt_(0) {}

    bool tryOperation() {
        if (currentAttempt_ < maxFailures_) {
            ++currentAttempt_;
            return doOperation();
        } else {
            reset();
            return false;
        }
    }

private:
    bool doOperation() {
        // Implement asynchronous operation with service_ and handle its result.
    }

    void reset() {
        if (currentAttempt_ < maxFailures_) {
            currentAttempt_ = 0;
            std::this_thread::sleep_for(std::chrono::seconds(cooldown_));
        }
    }
private:
    std::shared_ptr<SessionStorageService> service_;
    int maxFailures_, cooldown_, currentAttempt_;
};

