public class CustomSignInManager : SignInManager<ApplicationUser>
{
    public CustomSignInManager(IUserValidator<ApplicationUser> userValidator,
        IPasswordHasher<ApplicationUser> passwordHasher,
        IAuthenticationSchemeProvider schemes,
        IClientStore<ClaimsPrincipal> claimsFactory,
        HttpContextAccessor contextAccessor,
        IEventService events,
        UserManager<ApplicationUser> userManager,
        IMultiFactorAuthenticationService mfaService)
        : base(userValidator, passwordHasher, schemes, claimsFactory, contextAccessor, events, userManager)
    {
        _mfaService = mfaService;
    }

    private readonly IMultiFactorAuthenticationService _mfaService;

    public override async Task<SignInResult> PasswordSignInAsync(string userName, string password, bool isPersistent, bool lockoutOnFailure)
    {
        // Call base implementation to validate the password and user
        var result = await base.PasswordSignInAsync(userName, password, isPersistent, lockoutOnFailure);

        if (result.Succeeded && _mfaService != null)
        {
            // Call external MFA service to verify user's authentication
            var mfaResult = await _mfaService.VerifyAsync(Context.User.FindFirstValue("Sub"), password, Context.Request.Headers["MfaFactor1Token"]);
            if (!mfaResult) result = SignInResult.Failed;
        }

        return result;
    }
}
