const processDirectory = async (dirPath) => {
  const rl = readline.createInterface({
    input: fs.createReadStream(dirPath),
    crlfDelay: Infinity,
  });

  const filePromises = [];

  for await (const line of rl) {
    if (!line.startsWith('.')) { // Filter out hidden files
      const filePath = path.join(dirPath, line);
      const isSupportedExtension = supportedExtensions.includes(path.extname(filePath));

      if (isSupportedExtension) {
        filePromises.push(upload(filePath));
      }
    }
  }

  await bluebird.map(filePromises, bluebird.promisifyAll(fs.stat), { concurrency: 100 }); // Limit to 100 files at a time for efficient memory usage
};

// Start monitoring a specified directory for changes and initiate processing
const supportedExtensions = ['png', 'jpg', 'jpeg']; // Customize this array based on the desired file types
const watcher = chokidar.watch(process.env.WATCH_DIRECTORY, { persistent: true });

watcher.on('add', (filePath) => processDirectory(filePath));
watcher.on('change', (filePath) => processDirectory(filePath));

// Start the Express server and log port number used for health check endpoint
const port = parseInt(process.env.PORT);
app.listen(port, () => console.log(`Server started on port ${port}`));
