async function runTests(modulePath, options) {
  // Validate module path against the whitelist
  if (!WHITELIST.includes(modulePath)) {
    console.warn(`Invalid module path: ${modulePath}`);
    return;
  }

  try {
    // Dynamically load the module using require function
