    // Track the total number of tests and failed tests
    let completedTests = 0;
    let failedTests = 0;

    // Get all test functions from the loaded module
    const testFunctions = Object.values(module).filter(val => typeof val === 'function' && /^test/.test(val.name));

    // Execute each test asynchronously using Promises and handle errors gracefully
    const testPromises = testFunctions.map(testFunction =>
      bluebird.coroutine(function* () {
        try {
          yield blueslipInstance.reset(); // Reset the test environment before running each test
          testFunction();
          completedTests++;
          console.log(`Test ${completedTests} executed successfully`);
        } catch (error) {
          failedTests++;
          console.error(`Test ${completedTests} failed:`, error);
          console.trace(error.stack);
        }
      })()
    );

    // Execute all testPromises concurrently with a maximum concurrency limit (based on available CPU cores)
    const results = await bluebird.map(testPromises, bluebird.parallel((maxConcurrency) => maxConcurrency || 1));

    // Display the overall test suite progress in real-time for large-scale test suites
    console.log(`Completed ${completedTests} of ${testFunctions.length} tests`);
    console.log(`Failed ${failedTests} tests`);

