angular.module('app').service('DialogService', function ($http, $q, $window) {
    var fieldMap = {}; // Map dialog fields to updated values
    var booksCount = {}; // Map book names to their frequency count
    var activeRequests = 0;
    var maxConcurrentRequests = 5;

    this.refreshFields = function (resourceId, url, fieldNames) {
        if (activeRequests >= maxConcurrentRequests) return $q.defer().promise; // Limit concurrent requests

        activeRequests++;
        var promises = [];

        for (var i = 0; i < fieldNames.length; i++) {
            var name = fieldNames[i];
