```java
import akka.actor.Actor;
import akka.actor.ActorRef;
import akka.actor.Props;

public class MessageQueueActor extends Actor {
    private final ActorRef nioServer;

    public static Props props(ActorRef nioServer) {
        return Props.create(MessageQueueActor.class, () -> new MessageQueueActor(nioServer));
    }

    private MessageQueueActor(ActorRef nioServer) {
        this.nioServer = nioServer;
    }

    @Override
    public Receive createReceive() {
        return receiveBuilder()
                .match(String.class, message -> handleMessage(message))
                .build();
    }

    private void handleMessage(String message) {
        // Handle messages here and send them to the NioServer for processing.
    }
}
```

5. Create a main class to start the service:

```java
public class Main {
    public static void main(String[] args) {
        int port = 8080; // Set your desired port here.

        ActorSystem system = Akka.create(ActorSystem.class);

        final ActorRef messageQueueActor = system.actorOf(MessageQueueActor.props(system.actorSelection("user/nio-server")));

        NioServer nioServer = new NioServer(port);
        nioServer.start();

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            nioServer.stop();
            system.terminate();
        }));
    }
}
