<?php

// Configuration selector function for dynamic environment selection
function selectEnvironment($fallback = 'development') {
    // Implement your own logic for selecting the environment based on your requirements (e.g., checking environment variables, cookies, etc.)
    $env = getenv('ENVIRONMENT') ?? $_SERVER['REMOTE_ADDR'] ? substr($_SERVER['REMOTE_ADDR'], 0, 7) : $fallback;
    return strtolower($env);
}

// External API wrapper class for handling retries with exponential backoff and caching strategies
class ApiWrapper {
    private $cache = [];
    private $apiUrl;
    private $timeout;
    private $retryDelay;
    private $maxRetries;

    public function __construct($apiUrl, $timeout = 5, $retryDelay = 1000, $maxRetries = 3) {
        $this->apiUrl = $apiUrl;
        $this->timeout = $timeout;
        $this->retryDelay = $retryDelay;
        $this->maxRetries = $maxRetries;
    }

    public function get($path, $cacheKey = null) {
        if (isset($this->cache[$cacheKey])) {
            return $this->cache[$cacheKey];
        }

        $response = false;
        for ($i = 0; $i < $this->maxRetries && !$response; $i++) {
            $options = [
                'http' => [
                    'header' => "Content-type: application/json\r\n",
                    'timeout' => $this->timeout,
                ],
            ];

            $context = stream_context_create($options);
            $response = file_get_contents($this->apiUrl . '/' . $path, false, $context);

            if ($response !== false) {
                usleep($this->retryDelay << ($i + 1));
                $this->cache[$cacheKey] = json_decode($response, true);
            }
        }

        return $this->cache[$cacheKey];
    }
}

// Initialize the vendor autoloader and environment-specific configuration
