['1. C Program (`transaction_average.c`)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <getopt.h>
#include <csv.h>
#include <sys/stat.h>

CSV *csv;
pthread_mutex_t csv_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    size_t line_num;
    char data[4096];
} LineData;

void *process_line(void *data) {
    LineData *line = (LineData *)data;
    double num1, num2, avg;
    sscanf(line->data, "%lf%*c %lf", &num1, &num2);
    avg = (num1 + num2) / 2.0;
    pthread_mutex_lock(&csv_lock);
    csv_write_double(csv, line->line_num++, avg);
    pthread_mutex_unlock(&csv_lock);
    free(line->data);
    free(line);
    return NULL;
}

int main(int argc, char **argv) {
    struct stat sb;
    FILE *file;
    LineData *line_data;
    pthread_t threads[256]; // Adjust this number according to your requirements

    if (stat(argv[1], &sb) < 0) {
        perror("Error reading file");
        exit(EXIT_FAILURE);
    }

    file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    csv = csv_create(NULL, 0, CSV_NO_ESCAPE_CHARACTERS|CSV_NO_HEADER, NULL);
    if (!csv) {
        fprintf(stderr, "Error initializing CSV writer\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        line_data = malloc(sizeof(LineData));
        line_data->line_num = 0;
        size_t bytes_read = fread(line_data->data, 1, sizeof(line_data->data)-1, file);
        if (bytes_read < sizeof(line_data->data) - 1) {
            break;
        }
        line_data->data[sizeof(line_data->data)-1] = '\0';

        for (size_t i = 0; i < sizeof(threads)/sizeof(threads[0]); ++i) {
            if (!pthread_create(&threads[i], NULL, process_line, line_data)) {
                break;
            }
        }
    }

    for (size_t i = 0; i < sizeof(threads)/sizeof(threads[0]); ++i) {
        pthread_join(threads[i], NULL);
    }

    csv_destroy(csv);
    fclose(file);

    return EXIT_SUCCESS;
}
```

