#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <fstream>
#include <opencv2/opencv.hpp>

// Thread-safe queue for managing requests
class RequestQueue {
private:
    std::queue<std::function<void()>> m_requests;
    pthread_mutex_t m_mutex;
    pthread_cond_t m_notEmpty, m_notFull;

public:
    RequestQueue() : m_mutex(), m_notEmpty(PTHREAD_COND_INITIALIZER), m_notFull(PTHREAD_COND_INITIALIZER) {}

    void enqueue(std::function<void()> request) {
        pthread_mutex_lock(&m_mutex);
        m_requests.push(request);
        pthread_cond_signal(&m_notEmpty);
        pthread_mutex_unlock(&m_mutex);
    }

    void dequeue(std::function<void()>& request) {
        pthread_mutex_lock(&m_mutex);
        while (m_requests.empty()) {
            pthread_cond_wait(&m_notEmpty, &m_mutex);
        }
        request = m_requests.front();
        m_requests.pop();
        pthread_cond_signal(&m_notFull);
        pthread_mutex_unlock(&m_mutex);
    }
};

// Video processing function for each frame
void processFrame(const cv::VideoCapture& cap, RequestQueue* queue, int width, int height) {
    Mat frame;
    cap >> frame; // Get next frame from the video

    if (frame.empty()) { // Handle potential failures such as network timeouts
        printf("Error: Frame capture failed\n");
        return;
    }

    resize(frame, frame, Size(width, height)); // Resize frame based on user-specified settings

    std::string filename = generateThumbnailPath(cap.get(cv::CAP_PROP_FILENAME), width, height);
    imwrite(filename, frame); // Save thumbnail image to specified directory
}

// Helper function for generating thumbnail filenames
std::string generateThumbnailPath(const std::string& videoPath, int width, int height) {
    size_t lastSlash = videoPath.find_last_of('/');
    std::string directory = (lastSlash == std::string::npos) ? "" : videoPath.substr(0, lastSlash);
    std::string baseName = videoPath.substr(lastSlash + 1);

    return directory + "/thumb_" + baseName + "_" + std::to_string(width) + "_" + std::to_string(height) + ".jpg";
}

int main(int argc, char** argv) {
