    @PersistenceContext
    private EntityManager em;

    @Resource(name="tokenCache")
    private Cache<Long, JsonNode> tokenCache;

    @POST
    @Path("{operation}")
    public Response handleResourceLifecycle(@PathParam("operation") String operation, @QueryParam("id") Long tokenId, JsonNode payload) {
        try {
            switch (operation) {
                case "CREATE":
                    validatePayload(payload);
                    em.persist(mapToOAuthToken(payload));
                    break;
                case "READ":
                    return Response.ok(tokenCache.get(tokenId, () -> getLatestStateFromDB(tokenId))).build();
                case "UPDATE":
                    validatePayload(payload);
                    updateTokenInDB(tokenId, payload);
                    break;
                case "DELETE":
                    verifyOriginalAndRemove(tokenId);
                    break;
            }
        } catch (ExecutionException e) {
            // Handle cache errors here
        }
        return Response.ok().build();
    }

    private void validatePayload(JsonNode payload) {
        if (!isValidOAuthTokenPayload(payload)) {
            throw new IllegalArgumentException("Invalid OAuth token payload.");
        }
    }

    private boolean isValidOAuthTokenPayload(JsonNode payload) {
        Map<String, JsonNode> fields = payload.fields();
        return fields.keySet().containsAll(Map.of("access_token", "", "expires_in", "", "token_type", "", "refresh_token", "").keySet())
                && fields.get("token_type").asText().equalsIgnoreCase("Bearer")
                && fields.get("expires_in").asInt() > 0;
    }

