public class AsyncXmlConfigLoader
{
    private readonly ConcurrentDictionary<string, XDocument> _cache = new ConcurrentDictionary<string, XDocument>();

    public void LoadConfiguration(string filePath)
    {
        var cacheKey = GenerateCacheKey(filePath);
        if (_cache.TryGetValue(cacheKey, out var cachedConfig))
            return; // Configuration already loaded from the cache

        Task.Run(() => LoadFromXmlFileAsync(filePath)).ContinueWith(task =>
        {
            if (task.IsFaulted)
                _cache[cacheKey] = null; // Set a null value to indicate loading failed
            else
                _cache[cacheKey] = task.Result;
