    private readonly ConcurrentDictionary<string, object> _sharedResources = new ConcurrentDictionary<string, object>();

    public void SetSharedResource(string key, object value)
    {
        if (_sharedResources.ContainsKey(key))
            _sharedResources[key] = value; // Atomic operation, updates the shared resource safely
        else
            throw new KeyNotFoundException($"Resource '{key}' not found.");
    }

    public T GetSharedResource<T>(string key)
    {
        if (_sharedResources.TryGetValue(key, out var value))
            return (T)value; // Cast and return the shared resource safely
        else
            throw new KeyNotFoundException($"Resource '{key}' not found.");
    }
}
```

