async function acquireLock(key) {
  return await distributedLock.acquire({
    server: '<lock-server-url>', // Replace with your distributed lock server URL
    key,
    ttl: 60, // Timeout in seconds
    retryInterval: 1000 // Retry interval in milliseconds
  });
}

