  busboy.on('file', async (fieldname, file, _fn) => {
    if (!fs.existsSync(path.extname(file.filename))) return;
    activeUploads++;

    try {
      const ext = path.extname(file.filename);
      await processFile(file, ext);

      const cloudServices = ['service1', 'service2']; // List of supported services
      if (!cloudServices.includes(process.env[`UPLOAD_TO_${ext.toUpperCase()}`])) return;

      const token = await getAuthenticationToken(); // Implement your authentication logic here

