    } catch (err) {
      // Handle errors during file processing or upload
    } finally {
      activeUploads--;
      _fn();
    }
  });

  busboy.on('finish', () => {
    if (activeUploads === 0) res.sendStatus(200);
  });

  req.pipe(busboy);
});

// ... Additional code for error handling, rate limiting, logging, and metrics

function loadResourceBundle(filePath) {
  FILE *fp = fopen(filePath, "rb");
  if (!fp) return -1;

  size_t size = 0;
  fseek(fp, 0, SEEK_END);
  size = ftell(fp);
  rewind(fp);

  void* buffer = malloc(size);
  if (!buffer) {
    fclose(fp);
    return -1;
  }

  size_t bytesRead = fread(buffer, 1, size, fp);
  if (bytesRead != size) {
    free(buffer);
    fclose(fp);
    return -1;
  }

  int numItems = parseResourceBundle(buffer, size);
  free(buffer);
  fclose(fp);

  return numItems;
}
```']

