class LogAnalyzer:
    def __init__(self, api_base_url: str, retries: int = 3):
        self.api_base_url = api_base_url
        self.retries = retries
        self.worker_threads = min(os.cpu_count() * 2, 100)
        self.log_data: List[Dict] = []
        self.aggregation_criteria: Dict[str, Callable[[List[float]], float]] = {
            'count': sum,
            'average': lambda values: sum(values) / len(values),
            'max': max,
            'min': min,
        }

    def _load_logfile(self, filepath: str):
        with open(filepath) as f:
            for line in f:
                try:
                    entry = json.loads(line)
                    self.log_data.append(entry)
                except Exception as e:
                    print(f'Error processing log entry from {filepath}: {e}')

    def _lookup_metadata(self, entry: Dict):
        try:
            response = self._api_request({**entry, 'id': entry['id']})
            if response:
                entry.update(response)
            return entry
        except (RequestExceptions.RequestException, Exception) as e:
            print(f'Error fetching metadata for log entry {entry["id"]}: {e}')
            return entry

    def _api_request(self, data: Dict):
        session = Session()
        url = self.api_base_url + '/lookup'
        attempts = self.retries

        def api_wrapper():
            nonlocal attempts
            while attempts > 0:
                try:
                    return session.post(url, json=data).json()
                except RequestExceptions.RequestException as e:
                    if not isinstance(e, RequestExceptions.ConnectionError):
                        print(f'API error for log entry {data["id"]}: {e}')
                    attempts -= 1
                    time.sleep(5)
                    continue
            return None

        return api_wrapper()

    def process(self, logfile_paths: List[str]):
        with concurrent.futures.ThreadPoolExecutor(max_workers=self.worker_threads) as executor:
            tasks = [executor.submit(self._lookup_metadata, entry) for entry in self._load_logfile(logfile_) for logfile_ in logfile_paths]
            for future in concurrent.futures.as_completed(tasks):
                try:
                    result = future.result()
                    if result:
                        self.log_data.append(result)
                except Exception as e:
                    print(f'Error processing log file: {e}')

            gc.collect()

    def aggregate(self, criteria: List[Tuple[str, str]], functions: List[str]):
        grouped_data = {}

        for key, value in self.log_data[0].items():
            if key not in criteria[0][0]:
                continue
            group = criteria[0][1].get(key, key)
            if group not in grouped_data:
                grouped_data[group] = {'totals': {criteria[i][0]: [] for i, (_, f) in enumerate(zip(criteria, functions))}, 'count': 0}

        for entry in self.log_data:
            group = criteria[0][1].get(entry[criteria[0][0]], criteria[0][0])
            grouped_data[group]['count'] += 1
            for i, (_, f) in enumerate(zip(criteria, functions)):
                if f == 'count':
                    continue
                grouped_data['totals'][f[0]].append(entry[f[1]])

        result = []
        for group_name, group_data in grouped_data.items():
            aggregated_values = {}
            for key, values in group_data['totals'].items():
                aggregated_values[key] = self.aggregation_criteria[functions[i]](values)

            result.append({'group': group_name, **aggregated_values})
        return result

    def run(self, logfile_paths: List[str], criteria: List[Tuple[str, str]], functions: List[str]):
        self.process(logfile_paths)
        start_time = time.time()
        aggregated_results = self.aggregate(criteria, functions)
        end_time = time.time()
        elapsed_time = end_time - start_time

        print(f'Aggregation complete in {elapsed_time:.2f} seconds')
        print('Aggregated results:')
        for result in aggregated_results:
            print(result)

if __name__ == '__main__':
    api_base_url = 'https://logging-service.example.com/v1'  # Replace with your API base URL
    logfile_paths = ['logfile1.json', 'logfile2.json']  # Replace with paths to your JSON log files
    criteria = [('field1', 'lower'), ('field2', 'upper')]  # Replace with your custom aggregation criteria (field, grouping strategy)
    functions = ['count', 'average']  # Replace with the desired aggregation functions (count, average, max, min)
    analyzer = LogAnalyzer(api_base_url)
    analyzer.run(logfile_paths, criteria, functions)
```']

