// SecureFileService module
mod secure_file_service {
    use std::collections::{HashMap, HashSet};
    use std::sync::{Arc, Mutex, RwLock};
    use std::time::{Duration, SystemTime, UNIX_EPOCH};

    // Third-party dependencies (OAuth client, secure file storage service API)
    use oauth2 as o;
    use reqwest::{Client, Response};

    type Cache = Arc<RwLock<HashMap<String, Vec<u8>>>>;
    type TokenManager = Arc<Mutex<o::TokenManager<o::AccessTokenError>>>;

    struct SecureFileService {
        cache: Cache,
        token_manager: TokenManager,
        client: Client,
    }

    impl SecureFileService {
        pub async fn new(client_id: &str, client_secret: &str, refresh_token: &str) -> Self {
            let client = reqwest::Client::new();
            let token_manager = Arc::new(Mutex::new(o::TokenManagerBuilder::new()
                .access_token_error_kind(o::AccessTokenErrorKind::Unauthorized)
                .client_id(client_id)
                .client_secret(client_secret)
                .refresh_token(refresh_token)
                .build().await.unwrap()));
            let cache = Arc::new(RwLock::new(HashMap::new()));

            Self { client, token_manager, cache }
        }

        async fn refresh_token(&self) {
            // Refresh token logic goes here...
        }

        async fn get_pem_data(&self, key_id: &str) -> Result<Vec<u8>, Error> {
            let cache_key = format!("{}", key_id);
            let mut cache = self.cache.write().await;
            if let Some(pem_data) = cache.get(&cache_key) {
                return Ok(pem_data.clone());
            }

            let token_manager = self.token_manager.lock().await;
            if let Some(access_token) = token_manager.token().map(|m| m.access_token()) {
                let resp = self.client
                    .get(&format!("https://file-storage-api.com/v1/pem/{}&access_token={}", key_id, access_token))
                    .send()
                    .await?;

                if let Ok(body) = resp.text().await {
                    let pem_data = base64::decode_config(&body, base64::STANDARD).map_err(|e| Error::DecodeError(e))?;
                    cache.insert(cache_key, pem_data);
                    return Ok(pem_data);
                }
            }

            self.refresh_token().await;
            self.get_pem_data(key_id).await
        }
    }

    #[derive(Debug)]
    enum Error {
        NetworkError(reqwest::Error),
        DecodeError(base64::DecodeError),
        AccessTokenError(o::AccessTokenError),
    }
}
```
