private async storeMetric(metricName, metricValue): Promise<void> {
  const params = {
    TableName: 'UploadMetrics',
    Key: {
      metricName,
    },
    ExpressionAttributeValues: {
      ':v': metricValue,
    },
    UpdateExpression: 'SET uploadCount = uploadCount + :v',
  };

  return new Promise((resolve, reject) => {
    this.db.update(params, (error, data) => {
      if (error) {
        reject(error);
      } else {
        resolve();
      }
    });
  });
}
