    for _ in 0..config::MAX_ATTEMPTS {
        match client.post(config::LOGGING_SERVICE_URL)
                   .header("Content-Type", "application/json")
                   .json(&json!({"string": r, "identifier": identifier}))
                   .send()
                   .await {
