typedef struct {
    size_t start;
    size_t length;
} chunk;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
chunk chunks[4];
size_t num_chunks = 0;

void* process_line(void* arg) {
    size_t index = *(size_t*)arg;
    chunk* curr_chunk = &chunks[index];
    size_t start = curr_chunk->start;
    size_t length = curr_chunk->length;

    double sum = 0.0;
    for (size_t i = start; i < length; ++i += 2) {
        sum += atof(&logfile[i]);
    }

    pthread_mutex_lock(&mutex);
    sum /= chunks[index].length - 1;
    fprintf(csv, "%lf\n", sum);
    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    FILE* logfile = fopen("transactions.log", "r");
    if (!logfile) {
        printf("Error opening transactions.log\n");
        return 1;
    }

    fseek(logfile, 0, SEEK_END);
    size_t file_size = ftell(logfile);
    rewind(logfile);

    chunks[num_chunks].start = 0;
    chunks[num_chunks].length = (file_size + num_chunks) / (num_chunks + 1);
    ++num_chunks;

    csv = fopen("results.csv", "w");
    if (!csv) {
        printf("Error opening results.csv\n");
        return 1;
    }

    size_t num_threads = (num_chunks <= 4) ? num_chunks : 4;
    pthread_t threads[num_threads];
    size_t* thread_indices = malloc(sizeof(size_t) * num_threads);

    for (size_t i = 0; i < num_threads; ++i) {
        thread_indices[i] = chunks[i].start;
        pthread_create(&threads[i], NULL, process_line, &thread_indices[i]);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(logfile);
    fclose(csv);

    return 0;
}
```

