#include <sys/stat.h>
#include <fcntl.h>

typedef struct {
    uint64_t sum;
    size_t count;
} averager;

averager init_averager() {
    averager avg = { 0 };
    return avg;
}

void update_averager(averager* avg, double value) {
    if (avg->count == 0) {
        avg->sum = value;
        avg->count++;
    } else {
        avg->sum += value - avg->sum / avg->count;
        avg->count++;
    }
}

double get_average(averager* avg) {
    return avg->sum / avg->count;
}

