[" Due to the complexity of the task and the limitations of this platform, I'll provide you with a high-level design and code snippets for some key components.

1. **Cache Structure**
```c++
#include <unordered_map>
#include <list>
#include <mutex>

class Cache {
private:
    std::unordered_map<key_type, value_type> data;
    std::list<key_type> lru;
    size_t capacity;
    std::mutex mtx;

public:
    // Constructors and getters/setters omitted for brevity

    void put(const key_type& key, const value_type& value) {
        std::scoped_lock lock(mtx);
        if (size() >= capacity) {
            auto it = lru.begin();
            data.erase(*it);
            lru.pop_front();
        }
        data[key] = value;
        lru.push_back(key);
    }

    value_type get(const key_type& key) {
        std::scoped_lock lock(mtx);
        auto it = data.find(key);
        if (it != data.end()) {
            lru.remove(key);
            lru.push_back(key);
            return it->second;
        }
        return {};
    }
};
```

