For the requested C++ method that takes a string parameter and returns its MD5 hash using a standard library function, here is an example implementation:

```cpp
#include <openssl/sha.h>
#include <string>

std::string computeMd5(const std::string& data) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, data.c_str(), data.length());
    SHA256_Final(digest, &ctx);

    std::string result;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        std::stringstream ss;
        ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<unsigned int>(digest[i]);
        result += ss.str();
    }

    return result;
}
