        public void ModifyFileName(string directory, string pattern, string replacement)
        {
            foreach (var file in Directory.GetFiles(directory))
            {
                if (!File.Exists(file)) continue;

                var newName = ReplacePatternInFileName(file, pattern, replacement);
                if (File.Exists(newName)) continue; // Avoid name conflicts

                File.Move(file, newName);
            }
        }

        private string ReplacePatternInFileName(string filePath, string pattern, string replacement)
        {
            var builder = new StringBuilder(filePath);
            for (int i = 0; i < builder.Length; i++)
            {
                if (builder[i] == pathSeparator && i + pattern.Length <= builder.Length)
                {
                    if (builder.Substring(i, pattern.Length) == pattern)
                    {
                        builder.Replace(pattern, replacement);
                        break;
                    }
                }
            }
            return builder.ToString();
        }
    }

