def retry(func, retries=3, delay_base=1):
    def inner(*args, **kwargs):
        for _ in range(retries):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                if _ == retries - 1:
                    raise e
                delay = min(delay_base * (2 ** _), 60)
                print(f"Retrying in {delay} seconds due to failure.")
                time.sleep(delay)
    return inner

