    virtual void release(const std::shared_ptr<std::string>& resource) = 0;
};

class ResourceLogger : public ResourceManager {
private:
    std::atomic_int count_{0};
public:
    int acquire(const std::shared_ptr<std::string>& resource) override {
        ++count_;
        std::cout << "Insertion: " << *resource << "\n";
        return 0;
    }

    void release(const std::shared_ptr<std::string>& resource) override {}
};

class ConcurrentForwardList {
private:
    std::forward_list<std::shared_ptr<std::string>> list_;
    std::mutex mutex_;
    ResourceManager& resourceManager_;
public:
    explicit ConcurrentForwardList(ResourceManager& resourceManager) : resourceManager_(resourceManager) {}

    void insertAfterFirstOccurrence(const std::shared_ptr<std::string>& target, const std::shared_ptr<std::string>& newItem) {
        auto it = std::find_if(list_.cbegin(), list_.cend(), [target](auto& elem) { return *elem == *target; });

        if (it != list_.cend()) {
            std::unique_lock lock(mutex_);
            it++;
            if (it != list_.cend()) {
                resourceManager_.acquire(*newItem);
                lock.unlock();
                list_.insert AfterEqual(*it, newItem);
                resourceManager_.release(*newItem);
            } else {
                lock.unlock();
                list_.push_back(newItem);
            }
        } else {
            list_.push_back(newItem);
        }
    }
};
```

This implementation defines a `ConcurrentForwardList` class that wraps the given forward list and provides a thread-safe `insertAfterFirstOccurrence` function. It uses a mutex to protect access to the internal forward list, ensuring concurrent modifications are handled correctly. The ResourceManager interface is used for resource management, allowing you to provide specific implementations like ResourceLogger in the client code.

Additionally, you can create unit tests and stress tests to validate the function's correctness and robustness under various conditions:

```cpp
#include "gtest/gtest.h"
#include <thread>
#include <vector>

TEST(ConcurrentForwardListTest, InsertAfterFirstOccurrence) {
    ResourceLogger resourceLogger;
    ConcurrentForwardList list(resourceLogger);

    std::vector<std::shared_ptr<std::string>> items = {
        std::make_shared<std::string>("item1"),
        std::make_shared<std::string>("item2"),
        std::make_shared<std::string>("item3")
    };

    for (auto& item : items) {
        list.insertAfterFirstOccurrence(items[0], item);
    }

    EXPECT_EQ(list_.size(), 4);
}

TEST(ConcurrentForwardListTest, Concurrency) {
    ResourceLogger resourceLogger;
    ConcurrentForwardList list(resourceLogger);

    std::vector<std::shared_ptr<std::string>> items = {
        std::make_shared<std::string>("item1"),
        std::make_shared<std::string>("item2"),
        std::make_shared<std::string>("item3")
    };

    std::vector<std::thread> threads;
    for (size_t i = 0; i < 100; ++i) {
        threads.emplace_back([&list, items]() {
            for (auto& item : items) {
                list.insertAfterFirstOccurrence(items[0], item);
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    EXPECT_EQ(list_.size(), 4 * 100 + items.size());
}
```']

