typedef struct {
    char password[256];
    char connection_title[256];
    void (*callback)(const char*, int);
    int fd;
} RequestData;

// Function to check if a string is non-empty
bool is_non_empty(const char *str) {
    return (strlen(str) > 0);
}

pthread_mutex_t g_fd_lock = PTHREAD_MUTEX_INITIALIZER;

void release_resource(int fd) {
    close(fd);
}

// Asynchronous file reading function
void read_file_async(RequestData *request_data) {
    if (!is_non_empty(request_data->password)) {
        // Invalid password
        return;
    }

    if (strlen(request_data->connection_title) == 0) {
        // Invalid connection title
        return;
    }

    if (!request_data->callback) {
        // Invalid callback function
        return;
    }

    pthread_mutex_lock(&g_fd_lock);

    int fd = request_data->fd;
    struct stat sb;

    if (fstat(fd, &sb) == -1 || S_ISDIR(sb.st_mode)) {
        // Invalid file descriptor or points to a directory
        release_resource(fd);
        pthread_mutex_unlock(&g_fd_lock);
        return;
    }

    char buffer[4096];
    ssize_t bytes_read;

    while ((bytes_read = read(fd, buffer, sizeof(buffer))) > 0) {
        // Process the data asynchronously here...
        // Perform your custom logic for handling file content
    }

    if (bytes_read == -1 && errno != EAGAIN) {
        // Handle errors such as non-existent files, permission denied errors, and I/O timeouts
        release_resource(fd);
        pthread_mutex_unlock(&g_fd_lock);
        return;
    }

    if (bytes_read == -1 && errno == EAGAIN) {
        // If EAGAIN is encountered, the file reading can be considered complete.
        release_resource(fd);
    } else {
        // Handle unexpected errors and release resources
        release_resource(fd);
    }

    pthread_mutex_unlock(&g_fd_lock);

    // Call the callback function with the file content and an error code (if any)
    if (request_data->callback) {
        request_data->callback("File Content", 0);
    }
}

