public class Md5Service
{
    private readonly IMongoDatabase _database;

    public Md5Service(IMongoClient mongoClient)
    {
        _database = mongoClient.GetDatabase("YourDatabaseName");
    }

    public async Task<string> ComputeMd5Async(string content)
    {
        // Compute MD5 hash of the content
        using var md5 = MD5.Create();
        byte[] result = md5.ComputeHash(Encoding.UTF8.GetBytes(content));

        // Encode the hash as a hexadecimal string and store it in the database
        string hash = BitConverter.ToString(result).Replace("-", String.Empty);

        var collection = _database.GetCollection<KeyValuePair<string, DateTime>>("Hashes");
        await collection.InsertOneAsync(new KeyValuePair<string, DateTime>(hash, DateTime.UtcNow));

        return hash;
    }
}
