The code for creating the semaphore function in C using standard library functions is as follows:

```c
#include <semaphore.h>

sem_t* CSemaphore::create(int initialValue) {
    sem_t *semaphore = sem_open("mySemaphore", O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, initialValue);
    if (semaphore == SEM_FAILED) {
        throw std::runtime_error("Failed to create semaphore");
    }
    return semaphore;
}

void CSemaphore::deleteSemaphore(sem_t* semaphore) {
    int result = sem_close(semaphore);
    if (result != 0) {
        throw std::runtime_error("Failed to close semaphore");
    }
    result = sem_unlink("mySemaphore");
    if (result != 0) {
        throw std::runtime_error("Failed to unlink semaphore");
    }
}
```']

