```python
class TaskRetryManager:
    def __init__(self, max_retries, retry_delay):
        self.max_retries = max_retries
        self.retry_delay = retry_delay
        self.attempts = 0

    def retry(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            success = False
            while not success and self.attempts < self.max_retries:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    print(f"Task failed with error: {e}. Retrying...")
                    self.attempts += 1
                    time.sleep(self.retry_delay)
            if self.attempts == self.max_retries:
                raise Exception(f"Task failed after {self.attempts} retries.")
