```c
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node *next; // Next node in the list
    bool is_deleted;   // Flag for garbage collection
};

void garbage_collect(Node** head) {
    if (!head || !*head) return;

    Node *current = *head, *temp;
    while (current != NULL) {
        temp = current->next;
        if (current->is_deleted && current->next == NULL) {
            free(current);
            *head = temp;
        } else if (!current->is_deleted && current->next != NULL) {
            current = temp;
        }
    }
}
