  2. **C++ MD5 Hash Function**

```cpp
#include <openssl/sha.h>

std::string md5(const std::string& data) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    SHA1_CTX ctx;
    SHA1Init(&ctx);
    SHA1Update(&ctx, data.c_str(), data.length());
    SHA1Final(digest, &ctx);

    std::string result;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        std::stringstream ss;
        ss << std::hex << static_cast<unsigned int>(static_cast<unsigned char>(digest[i]));
        result += (ss.str().length() == 1) ? "0" + ss.str() : ss.str();
    }
    return result;
}
```

