    new_node->pdu = pdu;
    new_node->next = NULL;

    if (tail) {
        tail->next = new_node;
        tail = new_node;
    } else {
        head = tail = new_node;
    }
    sem_post(&queue_mutex);
    sem_post(&queue_not_empty);
}

void* process_crc_indications(void*) {
