#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <algorithm>
#include <boost/property_tree/ptree.hpp>
#include <boost/property_tree/xml_parser.hpp>

void parseFile(const std::string& inputFile, const std::string& outputFile, const std::string& rules) {
    std::ifstream ifs(inputFile);
    std::stringstream ss;
    ss << ifs.rdbuf();
    auto content = ss.str();

    boost::property_tree::ptree pt;
    boost::property_tree::read_xml(std::istringstream(rules), pt);

    std::ofstream ofs(outputFile);
    for (auto& rule : pt) {
        if (rule.second.get<std::string>("type") == "replace") {
            size_t start = content.find(rule.second.get<std::string>("from"));
            while (start != std::string::npos) {
                ofs << content.substr(0, start) << rule.second.get<std::string>("to") << content.substr(start + rule.second.get<std::string>("from").length());
                start = content.find(rule.second.get<std::string>("from"), start + rule.second.get<std::string>("to").length());
            }
        }
    }
}
