    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string City { get; set; }
        public string Address { get; set; }
    }

    public class DatabaseManager
    {
        private IDbConnection _dbConnection;
        private ICacheEntryRedisDatabase _redisCache;

        public DatabaseManager(IDbConnectionFactory dbConnectionFactory, ICacheEntryRedisDatabase redisCache)
        {
            _dbConnection = dbConnectionFactory.CreateConnection();
            _redisCache = redisCache;
        }

        public async Task<List<Employee>> GetEmployeesByManagerIdAsync(int managerId, CancellationToken cancellationToken)
        {
            var key = "employees_" + managerId;
            var cachedResult = _redisCache.GetHashEntry(key);

            if (cachedResult != null)
                return cachedResult.ToObject<List<Employee>>();

            using (var transaction = _dbConnection.BeginTransaction())
            {
                var employees = await _dbConnection.QueryAsync<Employee>(
                    "SELECT * FROM employees WHERE manager_id=@managerId", new { managerId }, null, true, cancellationToken, transaction);

                if (employees.Any())
                {
                    _redisCache.HashSet(key, employees);
                }

                transaction.Commit();
            }

            return employees;
        }
    }

    public class Program
    {
