        {
            var configurationBuilder = new ConfigurationBuilder()
                .SetBasePath(Directory.GetCurrentDirectory())
                .AddXmlFile("appsettings.xml");

            var configuration = configurationBuilder.Build();

            _configuration = configuration;
            _dbConnectionFactory = GetDatabaseConnectionFactory(configuration);
            _redisCache = ConnectionMultiplexer.Connect(_configuration.DatabaseConnectionString).GetDatabase();
            _databaseManager = new DatabaseManager(_dbConnectionFactory, _redisCache);

