```javascript
const WorkerPool = require('worker_pool');
const compression = require('compression');
const { encrypt, decrypt } = require('./encryption');
const metadataExtractor = require('./metadata-extractor');

class FileProcessor {
  constructor(config) {
    this.workPool = new WorkerPool({ numWorkers: config.workers });
  }

  processFile(file, transformations) {
    return new Promise((resolve, reject) => {
      const task = { file, transformations };
      this.workPool.queue(() => {
        try {
          // Apply transformation steps asynchronously and isolate failures per step
          compression.gzip(file.content, (err, compressedContent) => {
            if (err) return reject(err);
            const encryptedData = encrypt(compressedContent);
            metadataExtractor.extractMetadata(file.metadata, (err, metadata) => {
              if (err) return reject(err);
              // Continue with the next transformation steps using the extracted metadata and encrypted data
            });
          });
        } catch (error) {
          return reject(error);
        }
      });
    });
  }
}
```

