```python
from django.http import HttpResponse, JsonResponse
from django.utils.deprecation import MiddlewareMixin
import requests
from functools import wraps
import json
import time
import re
import cachetools
import dill  # Python serialization library
import os
import logging

class AsynchronousCache:
    def __init__(self, expire_after=300):
        self.cache = cachetools.TTLCache(maxsize=1000, ttl=expire_after)

class CacheDecorator:
    def __init__(self, async_cache: AsynchronousCache):
        self.async_cache = async_cache

    def __call__(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = f"{func.__name__}:{str(args)}:{str(kwargs)}"
            result = self.async_cache.get(key)
            if result is not None:
                return result
            start_time = time.time()
            result = func(*args, **kwargs)
            end_time = time.time()
            elapsed_time = end_time - start_time
            self.async_cache[key] = (result, elapsed_time)
            return result
        return wrapper

