void traverse(const json& config, const json& selector, std::function<void(json)> callback) {
    for (auto& item : config.items()) {
        if (match_selector(item.value(), selector)) {
            callback(item.value());
        }

        if (item.value().is_object()) {
            traverse(item.value(), selector, callback);
        }
    }
}

void run_traversal(const std::string& config_path, const json& selector, const std::string& output_format) {
    try {
        // Load the JSON configuration file
        json config = json::parse(boost::filesystem::read_file(config_path));

        // Traverse the nested JSON configuration file and call callback for matching components
        traverse(config, selector, [](const json& obj) {
            // Cache component definitions as needed
            std::string key = obj["url"].get<std::string>();
            if (cache.count(key) == 0) {
                std::shared_ptr<json> component;
                {
                    std::unique_lock<std::mutex> lock(cache_mutex);
                    if (cache.count(key) == 0) {
                        fetch_component(obj["url"].get<std::string>(), key);
                    }
                    component = cache[key];
                }
            }

            // Call the callback with the cached component definition
            obj.merge(*cache[key]);
            callback(obj);
        });

        // Handle output format
        if (output_format == "json") {
            std::cout << config.dump() << std::endl;
        } else if (output_format == "plaintext") {
            // Print the matching components as plain text, one per line
            for (auto& item : config.items()) {
                if (item.value().is_object() && match_selector(item.value(), selector)) {
                    std::cout << item.key() << ":" << std::endl;
                    item.value().dump(std::cout, 2);
                }
            }
        } else {
            throw std::runtime_error("Unsupported output format");
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
}

int main(int argc, char* argv[]) {
    cxxopts::Options options("json_traversal", "A program to dynamically traverse a nested JSON configuration file.");
    options.add_options()
        ("f", "Json file path", cxxopts::value<std::string>()->required())
        ("s", "Selector", cxxopts::value<json>()->implicit_value("{}"))
        ("o", "Output format (json or plaintext)", cxxopts::value<std::string>("json"))
        ("h, --help", "Print help");

    auto result = options.parse(argc, argv);

    if (result.count("help")) {
