#include <string.h>
char* addSlashIfNeeded(const char *input, size_t limit) {
    if (strlen(input) > limit) {
        return NULL;
    } else {
        char *output = malloc(limit + 1);
        strncpy(output, input, limit);
        output[limit] = '/';
        output[limit+1] = '\0';
        return output;
    }
}
