```javascript
async function loadScript(url, callback) {
    const script = document.createElement('script');
    script.src = url;

    script.onload = () => callback();
    script.onerror = () => console.error(`Error loading ${url}`);

    document.head.appendChild(script);
}

async function loadScripts(urls, parallel) {
    if (!urls.length) return;

    const promises = [];

    if (parallel) {
        urls.forEach((url) => {
            const promise = new Promise((resolve) => {
                loadScript(url, resolve);
            });
            promises.push(promise);
        });
    } else {
        for (let i = 0; i < urls.length; i++) {
            await loadScript(urls[i], () => {});
        }
    }

    if (parallel) {
        promises.forEach((promise) => promise.then(() => {
            // Execute the scripts here, for example: runScripts();
        }));
    }
}
