public class StringOperationsService {
    private static final Logger LOGGER = LoggerFactory.getLogger(StringOperationsService.class);
    private static final int MAX_CACHE_SIZE = 1000;
    private static final long CACHE_EXPTIME = 60L, CACHE_EXPIRATION_WRITEBACK = 30L;
    private LoadingCache<Long, StringNode> cache;
    private Deque<StringNode> forwardList = new ConcurrentLinkedDeque<>();
    private JedisPoolConfig jedisPoolConfig = new JedisPoolConfig();
    private JedisPool jedisPool = new JedisPool(jedisPoolConfig);

    public StringOperationsService() {
        cache = CacheBuilder.newBuilder()
                .maximumSize(MAX_CACHE_SIZE)
                .expireAfterWrite(CACHE_EXPTIME, TimeUnit.SECONDS)
                .removalListener((notification, evictionInfo) -> writeBackToDB(evictionInfo.getCause()))
                .build((key, value) -> {
                    try {
                        return getStringNodeFromRedisOrDB(key);
                    } catch (ExecutionException e) {
                        LOGGER.error("Error while getting string node from Redis or DB: {}", e.getMessage());
                        throw new RuntimeException(e);
                    }
                });
    }

    private StringNode getStringNodeFromRedisOrDB(Long key) throws ExecutionException {
        try (Jedis jedis = jedisPool.getResource()) {
            if (!jedis.exists(key.toString())) {
                EntityManager em = EntityManagerFactory.createDefault().createEntityManager();
                StringNode stringNode = em.find(StringNode.class, key);
                if (stringNode == null) {
                    throw new RuntimeException("String node not found in Redis or DB.");
                }
                return stringNode;
            } else {
                return jedis.hgetAll(key.toString());
            }
        }
    }

