use std::process::{Command, Stdio};
use std::time::Instant;

pub fn compile_with_hook(source: &str, destination: &str) -> i32 {
    let start = Instant::now();
    let mut cmd = Command::new("rustc");
    cmd.arg(source);
    cmd.arg("-o");
    cmd.arg(destination);
    cmd.stdin(Stdio::null());
    cmd.stdout(Stdio::null());
    cmd.stderr(Stdio::pipe());

    let compile_output = cmd.spawn().unwrap().wait_with_output().unwrap();
    if compile_output.status.success() {
        // Custom logging hook here, before and after compilation
        let elapsed = start.elapsed().as_secs_f64();
        println!("Compilation time: {} seconds", elapsed);
        // Retrieve resident set size (RSS) for before and after compilation here
    } else {
        eprintln!("Error while compiling: {}", String::from_utf8_lossy(&compile_output.stderr));
    }
    compile_output.status.code().unwrap_or(1) // Return the exit code of the compiled program
}
