```javascript
const axios = require('axios');

async function getAvatarFromAPI(userId) {
  const baseURL = 'https://api.example.com/avatars';
  const retries = 3;
  const delayFactor = 2;

  for (let i = 0; i < retries; i++) {
    try {
      const response = await axios.get(`${baseURL}/${userId}`);
      return response.data;
    } catch (error) {
      if (!error.isAxiosError || error.response?.status !== 503) {
        throw error;
      }

      console.log(`Retrying avatar API request in ${Math.pow(2, i + 1)} seconds...`);
      await new Promise(resolve => setTimeout(resolve, Math.pow(delayFactor, i + 1) * 1000));
    }
  }

  // Fallback to local backup service or throw an error if no fallback is available
  // ...
}
```

