        self.event_handlers = event_handlers
        self.notification_manager = NotificationManager(messaging_platforms, user_preferences)
        self.notification_queue = queue.Queue()

    def dispatch_events(self):
        while True:
            try:
                event = self.notification_queue.get_nowait()
                for handler in self.event_handlers:
                    handler.handle(event)
                self.notification_manager.send_notification(event.payload, event.payload['user_id'])
            except queue.Empty:
