2. Asynchronous Resource Loader (Node.js):

```javascript
const https = require('https');
const fs = require('fs');
const path = require('path');

class AsyncResourceLoader {
  constructor(config, fallback) {
    this.config = config;
    this.fallback = fallback;
  }

  // Load resources from remote server or local cache
  async load(key) {
    const bundlePath = path.join(__dirname, this.fallback[key]);
    if (fs.existsSync(bundlePath)) {
      return fs.readFileSync(bundlePath);
    }

    try {
      const res = await https.get(`${this.config.apiUrl}/${key}`);
      if (res.statusCode === 200) {
        return res.rawData;
      }
    } catch (err) {
      console.error(err);
    }

    // If failed to load from the server, fallback to local cache or throw an error
    if (this.fallback[key]) {
      return this.load(this.fallback[key]);
    }

    throw new Error(`Failed to load resource "${key}"`);
  }
}
```

