use llvm_ir::*;
use lexer::{Lexer, Token};

fn parse_and_generate_llvm(grammar: &str) -> Result<Module, Error> {
    let mut lexer = Lexer::new(grammar);
    let mut tokens = Vec::new();

    loop {
        match lexer.next_token() {
            Ok(Token::Eof) => break,
            Ok(token) => tokens.push(token),
            Err(e) => return Err(e),
