#include <iostream>
#include <openssl/sha.h>
#include <list>
#include <string>
#include <exception>
#include <stdexcept>

std::string md5_hash(const std::string& str) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, str.c_str(), str.length());
    SHA256_Final(digest, &ctx);

    std::string result;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        unsigned char byte = digest[i];
        result += std::string(2, std::to_hex(byte));
    }

    return result;
}

void insert_after(std::forward_list<std::string>& list, const std::string& search, const std::string& new_value) {
    auto it = list.begin();
    if (it != list.end() && *it == search) {
        list.insert(next(it), new_value);
    } else {
        throw std::runtime_error("Search string not found in the list.");
    }
}
