["1. C++ MD5 Hash Function:

```cpp
#include <openssl/sha.h>
#include <string>

std::string computeMD5(const std::string& str) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, str.c_str(), str.length());
    SHA256_Final(digest, &ctx);

    std::string result;
    for (size_t i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        result += std::hex(static_cast<int>(digest[i]), nullptr, 0);
    }
    return result;
}
```

