```cpp
#include <list>
#include <string>

void insertAfter(std::list<std::string>& list, const std::string& target, const std::string& toInsert) {
    auto it = list.begin();
    while (it != list.end() && (*it) != target) {
        ++it;
    }

    if (it != list.end()) {
        list.insert(++it, toInsert);
    }
}
```

