def compute_md5(file_path):
    with open(file_path, 'rb') as f:
        md5 = hashlib.md5()
        while chunk := f.read(4096):
            md5.update(chunk)
    return md5.hexdigest()

def validate_file_integrity(file_paths, checksums=None):
    if not checksums:
        checksums = {path: compute_md5(path) for path in file_paths}

    with ThreadPoolExecutor() as executor:
        results = executor.map(compute_md5, file_paths)
        for path, result in zip(file_paths, results):
            if checksums[path] != result:
                print(f'File {path} has integrity issues.')
