```python
import hashlib
import concurrent.futures
import requests

class FileIntegrityChecker:
    def __init__(self):
        self.checksums = {}

    def compute_chunked_hashes(self, filepath):
        with open(filepath, 'rb') as f:
            chunk_size = 65536
            hasher = hashlib.md5()
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                hasher.update(data)
                yield hasher.hexdigest()

    def validate_file_integrity(self, filepath, checksum):
        self.checksums[filepath] = checksum
        local_hashes = list(self.compute_chunked_hashes(filepath))
        externally_fetched_checksum = requests.get(f"https://api.example.com/checksum/{filepath}").json()["checksum"]
        assert externally_fetched_checksum == checksum, f"File integrity check failed for {filepath}"
