#include <pthread.h>
typedef struct Cache {
    NetworkInterfaceConfig **cache;
    int capacity;
    int size;
    pthread_mutex_t lock;
} Cache;

Cache *create_cache(int capacity) {
    // Initialize and allocate memory for the Cache struct
}

NetworkInterfaceConfig* get_from_cache(Cache *cache, const char *ssid) {
    pthread_mutex_lock(&cache->lock);
    int index = hash(ssid) % cache->capacity;
    NetworkInterfaceConfig *config = cache->cache[index];
    pthread_mutex_unlock(&cache->lock);
    return config;
}

void put_in_cache(Cache *cache, const char *ssid, NetworkInterfaceConfig *config) {
    pthread_mutex_lock(&cache->lock);
    int index = hash(ssid) % cache->capacity;
    cache->cache[index] = config;
    pthread_mutex_unlock(&cache->lock);
}
