        memset(&ctx, 0, sizeof(DES_ctx));

        // Initialize the context with the input string
        DES_init(&ctx, input_cstr, strlen(input_cstr), MD5_DIGEST_LENGTH);

        // Perform the encryption operation (assuming this library uses encryption for hashing)
        DES_final(digest, &ctx);

        // Print the resulting hash
        for (size_t i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            std::cout << std::hex << static_cast<int>(digest[i]) << " ";
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
}
