#include <boost/asio/io_service.hpp>
#include <boost/asio/ip/tcp.hpp>
#include <nlohmann/json.hpp>

// External video processing library interface
extern "C" {
  void process_video(const char* input_file, const char* output_file, int resolution, double aspect_ratio);
}

struct ThumbnailRequest {
  std::string input_file;
  std::string output_dir;
  cv::Size resolution;
  double aspect_ratio;
};

std::mutex requests_mutex;
std::condition_variable requests_cv;
std::vector<ThumbnailRequest> pending_requests;
int max_concurrency = 4;
bool running = true;

void worker() {
  while (running) {
    std::unique_lock<std::mutex> lock(requests_mutex);
    requests_cv.wait(lock, []{ return !pending_requests.empty() || !running; });

    if (!pending_requests.empty()) {
      ThumbnailRequest request = pending_requests.back();
      pending_requests.pop_back();
      lock.unlock();

      // Implement scaling strategies that trade off between image quality and processing time here
      process_video(request.input_file.c_str(), request.output_dir + "/thumbnail.jpg", request.resolution, request.aspect_ratio);
    }
  }
}

void handle_client(boost::asio::ip::tcp::socket& socket) {
  nlohmann::json j;
  try {
    socket >> j;
    ThumbnailRequest request = {j["input_file"], j["output_dir"], cv::Size(j["resolution"][0], j["resolution"][1]), j["aspect_ratio"]};

    std::unique_lock<std::mutex> lock(requests_mutex);
    pending_requests.push_back(request);
    lock.unlock();
    requests_cv.notify_one();

    socket.close();
  } catch (const std::exception& e) {
    // Handle errors, log and return appropriate status code
  }
}

int main() {
  boost::asio::io_service io_service;
  boost::asio::ip::tcp::acceptor acceptor(io_service, boost::asio::ip::tcp::endpoint(boost::asio::ip::tcp::v4(), 8080));

  for (int i = 0; i < max_concurrency; ++i) {
    std::thread worker_thread(&worker);
    worker_thread.detach();
  }

  boost::asio::ip::tcp::socket socket;
  while (running) {
    acceptor.accept(socket);
    std::thread client_thread(&handle_client, std::ref(socket));
    client_thread.detach();
  }
}
```
