    }
}

void LoggingFramework::stop() {
    // Stop worker threads and clean up resources.
}

void LoggingFramework::worker() {
    while (true) {
        std::unique_lock<std::mutex> lock(m_dataLock);
        m_dataLock.unlock(); // Unlock to allow other workers to add logs to the queue if it's not empty.

