#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <subprocess.h>

int jpeg_to_pdf(const char* inputJpeg, const char* outputPdf) {
    pid_t pid;
    int status;
    char* args[] = {"convert", inputJpeg, "-output", outputPdf, NULL};

    pid = fork();
    if (pid == 0) {
        execvp(args[0], args);
        perror("execvp failed");
        exit(1);
    } else {
        waitpid(pid, &status, 0);
        return WIFEXITED(status) ? WEXITSTATUS(status) : 1;
    }
}
