[" Here is a basic structure of the modular JavaScript service. I'll use Node.js with Express.js, Axios for API calls, Bluebird for promise handling, and Lodash for utility functions.

```javascript
const express = require('express');
const axios = require('axios');
const _ = require('lodash');
const bluebird = require('bluebird');

const app = express();
const booksCache = {}; // In-memory cache for biblical books list

app.post('/count', async (req, res) => {
  try {
    const text = req.body.text;

    if (!text) throw new Error('Text must be provided');

    let totalBooks = countBookReferences(text);

    // Fetch the biblical books list from the external API and validate the found book references
    if (!booksCache.length) {
      const response = await axios.get('https://api.example.com/biblical-books');
      booksCache = response.data;
    }

    const validBookReferences = totalBooks.filter(book => _.includes(booksCache, book));
    res.json({ count: validBookReferences.length });
  } catch (error) {
    res.status(400).send(error.message);
  }
});

function countBookReferences(text) {
  // Advanced regular expression to identify whole-word book mentions while ignoring punctuation and special characters
  const regex = /(\b([A-Z][a-z]+\s?)*\b)/g;
  let matches = [];

  while ((match = regex.exec(text)) !== null) {
    matches.push(match[1].toLowerCase());
  }

  return matches;
}
```

This code does not include caching strategies, asynchronous processing, error handling for external API requests, and extensive unit/integration tests and documentation. You can expand upon this base by adding these features and optimizing it for performance and scalability."]

