// Rate limiting and adaptive throttling using a sliding window approach.
struct RateLimiter {
    max_requests: u64,
    current_window: Window,
}
impl RateLimiter {
    fn new(max_requests: u64) -> Self {
        Self {
            max_requests,
            current_window: Window::new(),
        }
    }

    fn allow(&mut self, client_id: &str) -> bool {
        let mut locked = self.current_window.lock();
        if !locked.contains(client_id) {
            locked.insert(client_id);
            locked.clear_after(Duration::from_secs(60));
            return true;
        }
        false
    }
}

