#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} Record;

void memory_allocation(int n_records, long *offsets, int *keys, int min_val, int max_val) {
    Record *records = malloc(n_records * sizeof(Record));
    srand(time(NULL));

    for (int i = 0; i < n_records; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = min_val + (max_val - min_val) * rand() / RAND_MAX;
