use std::path::PathBuf;

fn set_directory(dir_name: &str) -> Result<(), Box<dyn std::error::Error> {
    let dir_path = PathBuf::from(dir_name);
    if env::var("DIRECTORY_PATH").is_err() {
        create_dir_all(&dir_path)?;
        env::set_var("DIRECTORY_PATH", &dir_path.to_str().unwrap());
