fn set_dir_env(name: &str, path: Option<&str>) -> Result<(), ()> {
    let current = env::var(name).ok();
    if let Some(ref current) = current {
        if path.is_none() {
            return Ok(());
        }
        if current == path {
            return Ok(());
        }
        eprintln!("Environment variable {} conflicts with existing value {}", name, current);
        return Err(());
    }

    match path {
        Some(path) => {
            create_dir_all(path).map_err(|e| {
                eprintln!("Failed to create directory {}: {}", path, e);
                ()
            })?;
            env::set_var(name, path);
            Ok(())
        }
        None => {
            remove_dir_all("./new_directory").map_err(|e| {
                eprintln!("Failed to remove old directory: {}", e);
                ()
            })?;
            create_dir_all("./new_directory").map_err(|e| {
                eprintln!("Failed to create new directory: {}", e);
                ()
            })?;
            env::set_var(name, "./new_directory");
            Ok(())
        }
    }
}
