    let current = process.env[name];

    if (current === path) {
        return;
    }

    if (!current && !path) {
        fs.rmdirSync('./new_directory', { recursive: true });
        fs.mkdirSync('./new_directory');
        process.env[name] = './new_directory';
        return;
    }

    if (current === path) {
        console.log(`Environment variable ${name} already set to ${path}`);
        return;
    }

    const existingDir = fs.realpathSync(current);
    const newDir = fs.realpathSync(path);

    if (existingDir === newDir) {
        console.log(`Environment variable ${name} already set to ${newDir}`);
        return;
    }

    console.error(`Conflicting directories: ${existingDir} and ${newDir}`);
    throw new Error('Directory conflict');
}
