class RateLimiter {
private:
    int _window_size;
    int _current_count;

public:
    RateLimiter(int window_size) : _window_size(window_size), _current_count(0) {}

    void increment() {
        if (_current_count < _window_size) {
            ++_current_count;
        }
    }

    bool isAllowed(int limit) const {
        return _current_count <= limit;
    }
};
