```c
#include <stdio.h>
#include <stdarg.h>
#include <time.h>

void log_error(const char* format, ...) {
    time_t now;
    struct tm* tm_now;
    char buffer[4096];
    va_list args;

    time(&now);
    tm_now = localtime(&now);

    snprintf(buffer, sizeof(buffer), "[%04d-%02d-%02d %02d:%02d:%02d.%03d] [ERROR] ",
            1900 + tm_now->tm_year, 1 + tm_now->tm_mon, tm_now->tm_mday,
            tm_now->tm_hour, tm_now->tm_min, tm_now->tm_sec, (int)(tm_now->tm_usec / 1000));

