import os
import time
import threading
import asyncio
import aiohttp
import caching
import logging
from typing import Dict, List, Any

class NetworkMetricsCollector:
    def __init__(self, config: Dict[str, str]):
        self.api_urls = config['base_stations']
        self.api_token = config['api_token']
        self.cache = caching.LRUCache(config['cache_size'])
        self.lock = threading.Lock()
        self.logger = logging.getLogger(__name__)

    async def _fetch_metrics(self, url: str) -> Dict[str, Any]:
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(url, headers={'Authorization': self.api_token}) as response:
                    return await response.json()
        except Exception as e:
            self.logger.error(f'Failed to fetch metrics from {url}: {e}')
            return {}

    def _collect_metrics(self, urls_to_fetch: List[str]):
        future_tasks = []
        for url in urls_to_fetch:
            future_task = self.asyncio.create_task(self._fetch_metrics(url))
            future_tasks.append(future_task)

        results = []
        for task in asyncio.as_completed(future_tasks):
            result = task.result()
            results.append(result)
        return results

    def collect_metrics(self):
        with self.lock:
            urls_to_fetch = [url for url in self.api_urls if not url in self.cache]
        if not urls_to_fetch:
            return {}

        cached_results = self.cache.get_multi(urls_to_fetch)
        metrics = self._collect_metrics(urls_to_fetch)

        for i, (url, cached_result, fetched_result) in enumerate(zip(urls_to_fetch, cached_results, metrics)):
            if not cached_result or fetched_result:
                self.cache[url] = fetched_result

        return {k: v for k, v in self.cache.items() if v}

