std::unordered_map<std::string, NIC> nicCollection;
std::mutex mtx;

void addNIC(const NIC& nic) {
    std::lock_guard<std::mutex> lock(mtx);
    if (nicCollection.count(nic.mac)) return;
    nicCollection[nic.mac] = nic;
}

NIC getNICByMAC(const std::string& mac) const {
    std::lock_guard<std::mutex> lock(mtx);
    auto it = nicCollection.find(mac);
    return it != nicCollection.end() ? it->second : NIC{};
}

void deleteNICByMAC(const std::string& mac) {
    std::lock_guard<std::mutex> lock(mtx);
    auto it = nicCollection.find(mac);
    if (it == nicCollection.end()) return;
    nicCollection.erase(it);
}

