['1. File Hasher Module (C++):

```cpp
#include <iostream>
#include <fstream>
#include <boost/filesystem.hpp>
#include <openssl/md5.h>
#include <atomic>
#include <thread>
#include <vector>
#include <future>

namespace fs = boost::filesystem;

std::atomic<bool> g_stop(false);

class FileHasher {
public:
    void processDirectory(const std::string& path, std::function<void(size_t, size_t)> callback) {
        std::vector<fs::path> paths;
        fs::recursive_directory_iterator end_itr;
        for (fs::recursive_directory_iterator itr(path); itr != end_itr; ++itr) {
            if (itr->is_regular_file())
                paths.push_back(itr->path());
        }

        std::vector<std::future<void>> futures;
        for (auto& path : paths) {
            futures.emplace_back(std::async(std::launch::async, &FileHasher::processFile, this, path, callback));
        }

        for (auto& future : futures)
            future.wait();
    }

    void processFile(const fs::path& filePath, std::function<void(size_t, size_t)> callback) {
        std::ifstream ifs(filePath.string(), std::ios::binary);
        if (!ifs) {
            // Handle exceptions such as file not found or permission denied
            std::cerr << "Error opening file: " << filePath << std::endl;
            return;
        }

        unsigned char buffer[1024];
        MD5_CTX ctx;
        MD5_Init(&ctx);

        size_t bytesRead = 0, totalBytes = 0;
        while (ifs.read(reinterpret_cast<char*>(buffer), sizeof(buffer))) {
            MD5_Update(&ctx, buffer, sizeof(buffer));
            bytesRead += sizeof(buffer);
            totalBytes += bytesRead;

            if (callback)
                callback(totalBytes, filePath.string().size());
        }

        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5_Final(digest, &ctx);

        // Convert the hash to a readable format and output it
        std::cout << "Hash of " << filePath << ": ";
        for (auto& byte : digest) {
            std::cout << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(byte);
        }
    }
};
```

