```javascript
const AWS = require('aws-sdk');
const kinesis = new AWS.Kinesis();

exports.handler = async (event) => {
  const streamName = event.Records[0].kinesis.streamName;
  const shardIterator = event.Records[0].kinesis.shardIterator;

  // Fetch data from Kinesis Stream
  let dataArray = await fetchDataFromKinesis(streamName, shardIterator);

  // Process the data here for anomaly detection
};

async function fetchDataFromKinesis(streamName, shardIterator) {
  const params = {
    ShardIterator: shardIterator,
    StreamARN: streamArn,
  };
  let lastShardIterator;
  do {
    const data = await kinesis.getRecords(params).promise();

    // Process the data here

    lastShardIterator = data[data.length - 1].ShardIterator;
    params.ShardIterator = lastShardIterator;
  } while (lastShardIterator);
}
