    dynamic_cache_manager.start()
    while True:
        action = input('Enter action (get/set/invalidate): ')
        if action == 'get':
            key = input('Enter key: ')
            print(dynamic_cache_manager.get(key))
        elif action == 'set':
            key = input('Enter key: ')
            value = input('Enter value: ')
            dynamic_cache_manager.set(key, value)
        elif action == 'invalidate':
            key = input('Enter key: ')
            dynamic_cache_manager.invalidate(key)
        else:
            print('Invalid action')

if __name__ == "__main__":
    main()
```']

