#include <chrono>
#include <vector>

class DataRetentionManager {
private:
  std::vector<Event> eventVector;
  std::mutex dataMutex;
  std::chrono::steady_clock::time_point retentionCutoff;
  int64_t retentionPeriodMillis;

public:
  DataRetentionManager(int64_t retentionPeriodMillis)
      : retentionPeriodMillis(retentionPeriodMillis),
        retentionCutoff(std::chrono::steady_clock::now() - std::chrono::milliseconds(retentionPeriodMillis)) {}

  void addEvent(const Event& event) {
    // Lock the mutex before modifying the data, to ensure thread safety.
    std::lock_guard<std::mutex> lock(dataMutex);

    if (std::chrono::steady_clock::now() - retentionCutoff > std::chrono::milliseconds(retentionPeriodMillis)) {
      eventVector.pop_front();
    }

    eventVector.push_back(event);
  }
};
