['1. C Program (`avg_transactions.c`)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <ctype.h>
#include <pthread.h>
#include <kafka/kafka.h>

KAFKA_TOPIC_t *topic;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int valid_num(const char *str) {
    if (!str || !*str) return 0;
    for (size_t i = 0; str[i]; ++i) {
        if (!isdigit(str[i])) return 0;
    }
    return 1;
}

long long validate_transaction(const char *line) {
    char *token = strtok(strdup(line), " ");
    if (!token || !valid_num(token)) return LLONG_MAX;
    long long num = atoll(token);
    if (num < -1e9 || num > 1e9) return LLONG_MAX;
    return num;
}

void* process_transactions(void *arg) {
    KAFKA_MESSAGE_t *msg;
    while ((msg = kafka_consume(topic, NULL)) != NULL) {
        const char *line = (const char *) msg->payload;
        long long transaction = validate_transaction(line);
        if (transaction != LLONG_MAX) {
            pthread_mutex_lock(&mutex);
                double avg = (double)(*(long long*)arg + transaction) / 2;
                *(long long *)arg = avg;
            pthread_mutex_unlock(&mutex);
        }
        kafka_message_destroy(msg);
    }
    return NULL;
}

int main() {
    const char *brokers = "localhost:9092";
    const char *topic_name = "transactions";
    long long avg = 0;
    kafka_set_version(KAFKA_V0_8_2_1);
    topic = kafka_topic_open(brokers, topic_name, KAFKA_APPL_RO_ consumers=1, 0);
    pthread_t thread;
    pthread_create(&thread, NULL, process_transactions, &avg);
    pthread_join(thread, NULL);
    kafka_topic_close(topic);
    // Save avg to CSV file here
}
```

