using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

public class HashID {
    private static readonly Dictionary<string, string> _cache = new Dictionary<string, string>();
    public static string ComputeMD5Hash(string transactionId) {
        if (_cache.TryGetValue(transactionId, out var result)) return result;
        lock (_cache) {
            if (_cache.TryGetValue(transactionId, out result)) return result;
            using (var md5 = MD5.Create()) {
                byte[] hash = md5.ComputeHash(Encoding.ASCII.GetBytes(transactionId));
                result = BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
                _cache[transactionId] = result;
            }
        }
        return result;
    }

    public static string GetMD5HashWithTimestamp(string transactionId) {
        var hash = ComputeMD5Hash(transactionId);
        DateTimeOffset now = DateTimeOffset.Now;
        return $"{hash}-{now:yyyyMMddHHmmssff}";
    }

    public static void HandleDuplicateTransactionIds(string transactionId) {
        var timestampedId = GetMD5HashWithTimestamp(transactionId);
        // Maintain audit trail here
    }
}
